BOSNode *bostree_select(BOSTree *tree, unsigned int index) {
        BOSNode *node = tree->root_node;
        while(node) {
                if(node->left_child_count <= index) {
                        index -= node->left_child_count;
                        if(index == 0) {
                                return node;
                        }
                        index--;
                        node = node->right_child_node;
                }
                else {
                        node = node->left_child_node;
                }
        }
        return node;
