    }

    r.borrow_mut().parent_node = p.borrow().parent_node.clone();

    let r_left = r.borrow().left_child_node.clone();
    let r_left_count = r.borrow().left_child_count;

    p.borrow_mut().right_child_node = r_left.clone();
    p.borrow_mut().right_child_count = r_left_count;

    if let Some(rl) = &r_left {
        rl.borrow_mut().parent_node = Some(Rc::downgrade(&p));
    }

    let p_left_depth = p.borrow().left_child_node.as_ref().map_or(0, |n| 1 + n.borrow().depth);
    let p_right_depth = p.borrow().right_child_node.as_ref().map_or(0, |n| 1 + n.borrow().depth);
    p.borrow_mut().depth = _imax(p_left_depth, p_right_depth);
    p.borrow_mut().parent_node = Some(Rc::downgrade(&r));

    r.borrow_mut().left_child_node = Some(p.clone());

    let p_left_count = p.borrow().left_child_count;
    let p_right_count = p.borrow().right_child_count;
    r.borrow_mut().left_child_count = p_left_count + p_right_count + 1;

    let r_left_depth = r.borrow().left_child_node.as_ref().map_or(0, |n| 1 + n.borrow().depth);
    let r_right_depth = r.borrow().right_child_node.as_ref().map_or(0, |n| 1 + n.borrow().depth);
    r.borrow_mut().depth = _imax(r_left_depth, r_right_depth);

    r
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        if let Some(root) = &self.root_node {
            root.borrow().left_child_count + root.borrow().right_child_count + 1
        } else {
            0
        }
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let mut node_opt = self.root_node.clone();
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;
        let mut is_left_child = false;

        while let Some(node) = node_opt {
            parent_node = Some(node.clone());
            let cmp = (self.cmp_function)(&key, &node.borrow().key);
            if cmp < 0 {
                node.borrow_mut().left_child_count += 1;
                node_opt = node.borrow().left_child_node.clone();
                is_left_child = true;
            } else {
                node.borrow_mut().right_child_count += 1;
                node_opt = node.borrow().right_child_node.clone();
                is_left_child = false;
            }
        }

        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_node.as_ref().map(Rc::downgrade),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        if let Some(parent) = parent_node {
            if is_left_child {
                parent.borrow_mut().left_child_node = Some(new_node.clone());
            } else {
                parent.borrow_mut().right_child_node = Some(new_node.clone());
            }

            let p_left_exists = parent.borrow().left_child_node.is_some();
            let p_right_exists = parent.borrow().right_child_node.is_some();

            if p_left_exists ^ p_right_exists {
                parent.borrow_mut().depth += 1;
                let mut current = parent.borrow().parent_node.as_ref().and_then(|w| w.upgrade());

                while let Some(curr) = current {
                    let new_left_depth = curr.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let new_right_depth = curr.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let max_depth = _imax(new_left_depth, new_right_depth);

                    if curr.borrow().depth != max_depth {
                        curr.borrow_mut().depth = max_depth;
                    } else {
                        break;
                    }

                    let mut next_curr = curr.borrow().parent_node.as_ref().and_then(|w| w.upgrade());

                    if new_left_depth == new_right_depth + 2 {
                        let left_child = curr.borrow().left_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&left_child) > 0 {
                            _bostree_rotate_left(self, left_child);
                        }
                        let rotated = _bostree_rotate_right(self, curr.clone());
                        next_curr = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    } else if new_right_depth == new_left_depth + 2 {
                        let right_child = curr.borrow().right_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&right_child) < 0 {
                            _bostree_rotate_right(self, right_child);
                        }
                        let rotated = _bostree_rotate_left(self, curr.clone());
                        next_curr = rotated.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    }

                    current = next_curr;
                }
            }
        } else {
            self.root_node = Some(new_node.clone());
        }

        new_node
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let bubble_up: Option<Rc<RefCell<BOSNode>>>;

        let left_exists = node.borrow().left_child_node.is_some();
        let right_exists = node.borrow().right_child_node.is_some();

        if left_exists && right_exists {
            let mut candidate: Rc<RefCell<BOSNode>>;
            let lost_child: Option<Rc<RefCell<BOSNode>>>;

            let left_depth = node.borrow().left_child_node.as_ref().unwrap().borrow().depth;
            let right_depth = node.borrow().right_child_node.as_ref().unwrap().borrow().depth;

            if left_depth >= right_depth {
                node.borrow_mut().left_child_count -= 1;
                candidate = node.borrow().left_child_node.as_ref().unwrap().clone();
                loop {
                    let has_right = candidate.borrow().right_child_node.is_some();
                    if has_right {
                        candidate.borrow_mut().right_child_count -= 1;
                        let next = candidate.borrow().right_child_node.as_ref().unwrap().clone();
                        candidate = next;
                    } else {
                        break;
                    }
                }
                lost_child = candidate.borrow().left_child_node.clone();
            } else {
                node.borrow_mut().right_child_count -= 1;
                candidate = node.borrow().right_child_node.as_ref().unwrap().clone();
                loop {
                    let has_left = candidate.borrow().left_child_node.is_some();
                    if has_left {
                        candidate.borrow_mut().left_child_count -= 1;
                        let next = candidate.borrow().left_child_node.as_ref().unwrap().clone();
                        candidate = next;
                    } else {
                        break;
                    }
                }
                lost_child = candidate.borrow().right_child_node.clone();
            }

            let bubble_start = candidate.borrow().parent_node.as_ref().unwrap().upgrade().unwrap();
            let is_left = bubble_start.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &candidate));
            if is_left {
                bubble_start.borrow_mut().left_child_node = lost_child.clone();
            } else {
                bubble_start.borrow_mut().right_child_node = lost_child.clone();
            }
            if let Some(lc) = &lost_child {
                lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
            }

            let node_parent = node.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(parent) = &node_parent {
                let is_left = parent.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, node));
                if is_left {
                    parent.borrow_mut().left_child_node = Some(candidate.clone());
                } else {
                    parent.borrow_mut().right_child_node = Some(candidate.clone());
                }
            } else {
                self.root_node = Some(candidate.clone());
            }
            candidate.borrow_mut().parent_node = node.borrow().parent_node.clone();

            candidate.borrow_mut().left_child_node = node.borrow().left_child_node.clone();
            candidate.borrow_mut().left_child_count = node.borrow().left_child_count;
            candidate.borrow_mut().right_child_node = node.borrow().right_child_node.clone();
            candidate.borrow_mut().right_child_count = node.borrow().right_child_count;

            if let Some(cl) = candidate.borrow().left_child_node.as_ref() {
                cl.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }
            if let Some(cr) = candidate.borrow().right_child_node.as_ref() {
                cr.borrow_mut().parent_node = Some(Rc::downgrade(&candidate));
            }

            if !Rc::ptr_eq(&bubble_start, node) {
                let mut current = bubble_start;
                while !Rc::ptr_eq(&current, &candidate) {
                    let left_depth = current.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let right_depth = current.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    current.borrow_mut().depth = _imax(left_depth, right_depth);

                    let balance = _bostree_balance(&current);
                    if balance > 1 {
                        let right_child = current.borrow().right_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&right_child) < 0 {
                            _bostree_rotate_right(self, right_child);
                        }
                        current = _bostree_rotate_left(self, current.clone());
                    } else if balance < -1 {
                        let left_child = current.borrow().left_child_node.as_ref().unwrap().clone();
                        if _bostree_balance(&left_child) > 0 {
                            _bostree_rotate_left(self, left_child);
                        }
                        current = _bostree_rotate_right(self, current.clone());
                    }

                    let next = current.borrow().parent_node.as_ref().unwrap().upgrade().unwrap();
                    current = next;
                }
            }

            let c_left_depth = candidate.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
            let c_right_depth = candidate.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
            candidate.borrow_mut().depth = _imax(c_left_depth, c_right_depth);

            bubble_up = candidate.borrow().parent_node.as_ref().and_then(|w| w.upgrade());

            if let Some(bu) = &bubble_up {
                let is_left = bu.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &candidate));
                if is_left {
                    bu.borrow_mut().left_child_count -= 1;
                } else {
                    bu.borrow_mut().right_child_count -= 1;
                }
            }
        } else {
            let node_parent = node.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if node_parent.is_none() {
                if let Some(left) = node.borrow().left_child_node.as_ref() {
                    self.root_node = Some(left.clone());
                    left.borrow_mut().parent_node = None;
                } else if let Some(right) = node.borrow().right_child_node.as_ref() {
                    self.root_node = Some(right.clone());
                    right.borrow_mut().parent_node = None;
                } else {
                    self.root_node = None;
                }
                bubble_up = None;
            } else {
                let parent = node_parent.unwrap();
                let mut candidate = node.borrow().left_child_node.clone();
                let mut candidate_count = node.borrow().left_child_count;
                if node.borrow().right_child_node.is_some() {
                    candidate = node.borrow().right_child_node.clone();
                    candidate_count = node.borrow().right_child_count;
                }

                let is_left = parent.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, node));
                if is_left {
                    parent.borrow_mut().left_child_node = candidate.clone();
                    parent.borrow_mut().left_child_count = candidate_count;
                } else {
                    parent.borrow_mut().right_child_node = candidate.clone();
                    parent.borrow_mut().right_child_count = candidate_count;
                }

                if let Some(c) = &candidate {
                    c.borrow_mut().parent_node = Some(Rc::downgrade(&parent));
                }
                bubble_up = Some(parent);
            }
        }

        let mut bubbling_finished = false;
        let mut current_bubble = bubble_up;
        while let Some(bu) = current_bubble {
            let mut bu_ref = bu.clone();
            if !bubbling_finished {
                let left_depth = bu_ref.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let right_depth = bu_ref.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let new_depth = _imax(left_depth, right_depth);
                let depth_changed = new_depth != bu_ref.borrow().depth;
                bu_ref.borrow_mut().depth = new_depth;

                let balance = _bostree_balance(&bu_ref);
                if balance < -1 {
                    let left_child = bu_ref.borrow().left_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&left_child) > 0 {
                        _bostree_rotate_left(self, left_child);
                    }
                    bu_ref = _bostree_rotate_right(self, bu_ref.clone());
                } else if balance > 1 {
                    let right_child = bu_ref.borrow().right_child_node.as_ref().unwrap().clone();
                    if _bostree_balance(&right_child) < 0 {
                        _bostree_rotate_right(self, right_child);
                    }
                    bu_ref = _bostree_rotate_left(self, bu_ref.clone());
                } else {
                    if !depth_changed {
                        bubbling_finished = true;
                    }
                }
            }

            let parent_opt = bu_ref.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(parent) = &parent_opt {
                let is_left = parent.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &bu_ref));
                if is_left {
                    parent.borrow_mut().left_child_count -= 1;
                } else {
                    parent.borrow_mut().right_child_count -= 1;
                }
            }
            current_bubble = parent_opt;
        }

        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        let mut count = node.borrow().weak_ref_count;
        count -= 1;
        node.borrow_mut().weak_ref_count = count;
        if count == 0 {
            if let Some(free_fn) = self.free_function {
                free_fn(node);
            }
            None
        } else if node.borrow().weak_ref_node_valid != 0 {
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut node_opt = self.root_node.clone();
        while let Some(node) = node_opt.clone() {
            let cmp = (self.cmp_function)(key, &node.borrow().key);
            if cmp == 0 {
                return Some(node);
            } else if cmp < 0 {
                node_opt = node.borrow().left_child_node.clone();
            } else {
                node_opt = node.borrow().right_child_node.clone();
            }
        }
        None
    }

    pub fn bostree_select(&self, mut index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut node_opt = self.root_node.clone();
        while let Some(node) = node_opt.clone() {
            let left_count = node.borrow().left_child_count;
            if left_count <= index {
                index -= left_count;
                if index == 0 {
                    return Some(node);
                }
                index -= 1;
                node_opt = node.borrow().right_child_node.clone();
            } else {
                node_opt = node.borrow().left_child_node.clone();
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    node.borrow_mut().weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(right) = node.borrow().right_child_node.clone() {
        let mut curr = right;
        loop {
            let left = curr.borrow().left_child_node.clone();
            if let Some(l) = left {
                curr = l;
            } else {
                break;
            }
        }
        Some(curr)
    } else {
        let mut curr = node.clone();
        loop {
            let parent = curr.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(p) = parent {
                let is_right = p.borrow().right_child_node.as_ref().map_or(false, |r| Rc::ptr_eq(r, &curr));
                if is_right {
                    curr = p;
                } else {
                    return Some(p);
                }
            } else {
                return None;
            }
        }
    }
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if let Some(left) = node.borrow().left_child_node.clone() {
        let mut curr = left;
        loop {
            let right = curr.borrow().right_child_node.clone();
            if let Some(r) = right {
                curr = r;
            } else {
                break;
            }
        }
        Some(curr)
    } else {
        let mut curr = node.clone();
        loop {
            let parent = curr.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(p) = parent {
                let is_left = p.borrow().left_child_node.as_ref().map_or(false, |l| Rc::ptr_eq(l, &curr));
                if is_left {
                    curr = p;
                } else {
                    return Some(p);
                }
            } else {
                return None;
            }
        }
    }
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut curr_opt = Some(node.clone());
    while let Some(curr) = curr_opt {
        let parent_opt = curr.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
        if let Some(parent) = parent_opt.clone() {
            let is_right = parent.borrow().right_child_node.as_ref().map_or(false, |r| Rc::ptr_eq(r, &curr));
            if is_right {
                counter += 1 + parent.borrow().left_child_count;
            }
        }
        curr_opt = parent_opt;
    }
    counter
}
